// Preparer la traduction pour revision Discord
const input = $input.first().json;
const body = input.body || input;
const webhook = $env.N8N_BASE_URL;
const webhookBase = $env.N8N_WEBHOOK_BASE_URL;
const apiUrl = $env.API_URL;

const translation_id = body.translation_id || `tr_${Date.now()}`;
const reference = body.reference || 'Unknown Reference';

// Construire le texte source (tronque si trop long)
let sourceText = body.source_text || body.hebrew_text || '';
if (sourceText.length > 500) {
  sourceText = sourceText.substring(0, 500) + '...';
}

// Construire la traduction (tronque si trop long)
let translationText = body.translation || body.translated_text || '';
if (translationText.length > 800) {
  translationText = translationText.substring(0, 800) + '...';
}

// Commentaires traduits
const commentaries = body.commentaries || [];
const commentaryFields = commentaries.slice(0, 3).map((c, i) => ({
  name: c.commentator || `Commentaire ${i + 1}`,
  value: (c.translation || c.text || '').substring(0, 200) + (c.translation?.length > 200 ? '...' : ''),
  inline: false
}));

// URLs de callback pour les actions
const baseUrl = webhookBase + '/torah-review-action';
const approveUrl = `${baseUrl}?translation_id=${translation_id}&action=approve`;
const rejectUrl = `${baseUrl}?translation_id=${translation_id}&action=reject`;
const retranslateUrl = `${baseUrl}?translation_id=${translation_id}&action=retranslate`;

return [{
  json: {
    translation_id,
    reference,
    sourceText,
    translationText,
    commentaryFields,
    commentariesCount: commentaries.length,
    approveUrl,
    rejectUrl,
    retranslateUrl,
    submittedAt: new Date().toISOString()
  }
}];

