parameters.jsCode:
// Traiter l'action de revision
const input = $input.first().json;
const body = input.body || input;
const query = input.query || {};

// Supporter les parametres en body ou query string
const translation_id = body.translation_id || query.translation_id;
const action = body.action || query.action;
const feedback = body.feedback || query.feedback || '';
const reviewer = body.reviewer || query.reviewer || 'Anonymous';

// Validation
const validActions = ['approve', 'reject', 'retranslate'];
if (!translation_id) {
  return [{ json: { error: 'translation_id required', valid: false } }];
}
if (!validActions.includes(action)) {
  return [{ json: { error: `Invalid action. Use: ${validActions.join(', ')}`, valid: false } }];
}

// Mapping des statuts
const statusMap = {
  'approve': { status: 'approved', color: 5763719, emoji: '' },
  'reject': { status: 'rejected', color: 15548997, emoji: '' },
  'retranslate': { status: 'pending_retranslation', color: 15105570, emoji: '' }
};

const result = statusMap[action];

return [{
  json: {
    valid: true,
    translation_id,
    action,
    status: result.status,
    color: result.color,
    emoji: result.emoji,
    feedback,
    reviewer,
    processedAt: new Date().toISOString()
  }
}];

